import{_ as e,o as a,c as t,a2 as l}from"./chunks/framework.vLhlLNVn.js";const h=JSON.parse('{"title":"Ubuntu目录说明","description":"","frontmatter":{"title":"Ubuntu目录说明","author":"麻瓜【码瓜】","date":"2026-11-19"},"headers":[],"relativePath":"posts/catlog.md","filePath":"posts/catlog.md","lastUpdated":1795056562000}'),c={name:"posts/catlog.md"};function d(r,o,u,i,s,n){return a(),t("div",null,[...o[0]||(o[0]=[l('<h1 id="ubuntu目录说明" tabindex="-1">Ubuntu目录说明 <a class="header-anchor" href="#ubuntu目录说明" aria-label="Permalink to &quot;Ubuntu目录说明&quot;">​</a></h1><h2 id="自己写的二进制、自己写的脚本" tabindex="-1">自己写的二进制、自己写的脚本 <a class="header-anchor" href="#自己写的二进制、自己写的脚本" aria-label="Permalink to &quot;自己写的二进制、自己写的脚本&quot;">​</a></h2><p>优先 <code>/usr/local/bin</code>；管理员后台工具放 <code>/usr/local/sbin</code></p><h2 id="目录清单-按场景" tabindex="-1">目录清单（按场景） <a class="header-anchor" href="#目录清单-按场景" aria-label="Permalink to &quot;目录清单（按场景）&quot;">​</a></h2><h3 id="_1-系统自带-apt-安装-不要手动放这里" tabindex="-1">1. 系统自带（apt 安装，不要手动放这里！） <a class="header-anchor" href="#_1-系统自带-apt-安装-不要手动放这里" aria-label="Permalink to &quot;1. 系统自带（apt 安装，不要手动放这里！）&quot;">​</a></h3><ul><li><code>/usr/bin</code>：普通用户命令，<code>ls</code>、<code>nginx</code>、<code>git</code>、<code>python3</code>，apt 安装的程序都在这里</li><li><code>/usr/sbin</code>：root 管理员命令，<code>systemctl</code>、<code>iptables</code>、<code>sshd</code></li><li><code>/bin</code> / <code>/sbin</code>：新版 Ubuntu 只是软链接指向 <code>/usr/bin</code>，兼容老系统，<strong>不建议手动放东西</strong></li></ul><blockquote><p>这些目录属于系统包管理，<code>apt upgrade</code> 会覆盖里面文件</p></blockquote><h3 id="_2-管理员手动部署-你最常用-xray-就属于这类" tabindex="-1">2. 管理员手动部署（你最常用，xray 就属于这类） <a class="header-anchor" href="#_2-管理员手动部署-你最常用-xray-就属于这类" aria-label="Permalink to &quot;2. 管理员手动部署（你最常用，xray 就属于这类）&quot;">​</a></h3><ul><li><code>/usr/local/bin</code>：<strong>全局可用、所有用户都能跑</strong>，自己编译的 Go 二进制、下载的独立程序、shell/python 脚本（推荐首选）Ubuntu</li></ul><blockquote><p>系统中的 <code>/usr/local/bin/xray</code> 就是这个规范！</p></blockquote><ul><li><code>/usr/local/sbin</code>：<strong>只有 root 用的本地工具</strong>，后台守护、运维脚本，普通用户 PATH 一般不带这个</li></ul><blockquote><p><code>/usr/local</code> 整个目录<strong>apt 不会碰，升级系统不会覆盖</strong>，这是它最大优势Linux Foun...</p></blockquote><h3 id="_3-仅当前用户自己用-不需要-sudo" tabindex="-1">3. 仅当前用户自己用（不需要 sudo） <a class="header-anchor" href="#_3-仅当前用户自己用-不需要-sudo" aria-label="Permalink to &quot;3. 仅当前用户自己用（不需要 sudo）&quot;">​</a></h3><ul><li><code>~/.local/bin</code>（XDG 标准，推荐），现代 Ubuntu 默认进 PATH</li><li><code>~/bin</code>：老传统目录，部分 shell 会自动加入 PATH</li></ul><blockquote><p>只有你这个用户能调用，别的用户看不到，放个人小脚本、自用工具</p></blockquote><h3 id="_4-完整独立打包程序-比如带一堆依赖-资源" tabindex="-1">4. 完整独立打包程序（比如带一堆依赖 / 资源） <a class="header-anchor" href="#_4-完整独立打包程序-比如带一堆依赖-资源" aria-label="Permalink to &quot;4. 完整独立打包程序（比如带一堆依赖 / 资源）&quot;">​</a></h3><ul><li><code>/opt/xxx/</code>：整套软件放这里（比如 <code>/opt/myservice/</code>），然后在 <code>/usr/local/bin</code> 建软链接指向主程序</li></ul><blockquote><p>适合一整个文件夹的程序，不是单个二进制</p></blockquote><h3 id="_5-内部辅助脚本-不给用户直接敲命令调用" tabindex="-1">5. 内部辅助脚本（不给用户直接敲命令调用） <a class="header-anchor" href="#_5-内部辅助脚本-不给用户直接敲命令调用" aria-label="Permalink to &quot;5. 内部辅助脚本（不给用户直接敲命令调用）&quot;">​</a></h3><ul><li><code>/usr/libexec/</code> 或者跟着服务放，systemd 内部调用，一般不在 PATH 里</li></ul>',20)])])}const p=e(c,[["render",d]]);export{h as __pageData,p as default};
